(()=>{const hero=document.querySelector('.hero'),panel=hero.querySelector('#hero-panel'),top=hero.querySelector('.hero-identity'),bottom=top.cloneNode(true),reduce=matchMedia('(prefers-reduced-motion:reduce)');bottom.classList.add('curtain-bottom');bottom.setAttribute('aria-hidden','true');bottom.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));panel.append(bottom);let frame=0;function paint(){frame=0;const p=reduce.matches?0:Math.max(0,Math.min(1,-hero.getBoundingClientRect().top/innerHeight));top.style.transform=`translateY(${-p*55}%)`;bottom.style.transform=`translateY(${p*55}%)`;hero.style.visibility=p>=1?'hidden':'visible';bottom.inert=p>.8;}function queue(){if(!frame)frame=requestAnimationFrame(paint)}addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);paint()})();
